import{_ as t,o,c as n,j as e,a as r}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/57-安全缓冲效应.md","filePath":"books/attached/57-安全缓冲效应.md","lastUpdated":1794298621000}'),s={name:"books/attached/57-安全缓冲效应.md"};function l(d,a,c,i,_,p){return o(),n("div",null,[...a[0]||(a[0]=[e("h3",{id:"安全缓冲效应",tabindex:"-1"},[r("安全缓冲效应 "),e("a",{class:"header-anchor",href:"#安全缓冲效应","aria-label":'Permalink to "安全缓冲效应"'},"​")],-1),e("p",null,"相关研究结果不止一次显示，能在恋爱中带来最高幸福感的，正是安全型依恋风格的人群。这些研究显示，相比于其他依恋风格的人，安全型人群的确有着更高的恋爱满意度。帕特里克·基兰（Patrick Keelan）在多伦多大学的博士论文中，有一个部分就是设计了实验来验证这个议题。而这项研究的合作者，还有已故的心理学教授肯尼斯·迪翁（Kenneth Dion）以及同为多伦多大学心理学教授，肯尼斯的妻子卡伦·迪翁（Karen Dion），也是他多年来的研究拍档。他们的研究对象是一百余位持续恋爱四个月以上的大学生。他们发现，安全型依恋风格的个体，在恋爱中保持着较高的满意度、信任度以及确定性。而与之相反，非安全型依恋风格的人，同样恋爱四个月期间，以上三项指标则相对要弱。",-1),e("p",null,"那么安全型人群和非安全型伴侣接触的时候，会发生什么呢？在另一个实验中，研究者们则着重观察与测量伴侣双方对亲密关系功能性的认同。测试结果不出所料，两人都是安全型的组合，自然表示彼此的关系更加有效，而伴侣双方均属于焦虑型或回避型依恋风格的组合，亲密关系承担的功能性就相对弱些。更有趣的地方在于，安全型伴侣和“混合安全型”伴侣（即只有一位安全型成员的组合），两种类型对亲密关系的功能评价没有显著的差异。相比于两人都不属于安全型的伴侣，安全型与“混合安全型”伴侣都显示出更少的冲突和功能性更强的亲密关系。",-1),e("p",null,"因此，安全型依恋风格的人，不仅本身在恋爱关系中表现得更好，他们还会制造一种缓冲效应。在一定程度上，这种效应可以帮助他们的非安全型伴侣将恋爱满意度和功能性提升到跟自己一样的高度。这项发现非常重要。即使你不是安全型依恋风格，只要找到安全型的伴侣，他们就会将你塑造成为更有安全感的状态。",-1)])])}const f=t(s,[["render",l]]);export{m as __pageData,f as default};
